import{_ as e,o as t,c as l,a0 as r}from"./chunks/framework.DqMqoJl9.js";const h=JSON.parse('{"title":"子网掩码","description":"","frontmatter":{},"headers":[],"relativePath":"network/4-subnet.md","filePath":"network/4-subnet.md","lastUpdated":1791573371000}'),i={name:"network/4-subnet.md"};function o(n,a,s,_,p,d){return t(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="子网掩码" tabindex="-1">子网掩码 <a class="header-anchor" href="#子网掩码" aria-label="Permalink to &quot;子网掩码&quot;">​</a></h1><p>子网掩码(subnet mask)又叫网络掩码、地址掩码、子网络遮罩，它是一种用来指明一个IP地址的哪些位标识的是主机所在的子网，以及 哪些位标识的是主机的位掩码。子网掩码不能单独存在，它必须结合IP地址一起使用。子网掩码只有一个作用，就是将某个IP地址划分成 网络地址和主机地址两部分</p><h2 id="_1-定义" tabindex="-1">1 定义 <a class="header-anchor" href="#_1-定义" aria-label="Permalink to &quot;1 定义&quot;">​</a></h2><p>子网掩码是一个32位地址，用于屏蔽IP地址的一部分以区别网络标识和主机标识，并说明该IP地址是在局域网上，还是在远程网上</p><ul><li>A类地址，默认的子网掩码是 255.0.0.0</li><li>B类地址，默认的子网掩码是 255.255.0.0</li><li>C类地址，默认的子网掩码是 255.255.255.0</li></ul><p>利用子网掩码可以把大的网络划分成子网，即VLSM（可变长子网掩码），也可以把小的网络归并成大的网络即超网</p><h2 id="_2-定义子网掩码" tabindex="-1">2 定义子网掩码 <a class="header-anchor" href="#_2-定义子网掩码" aria-label="Permalink to &quot;2 定义子网掩码&quot;">​</a></h2><p>用于子网掩码的位数决定于可能的子网数目和每个子网的主机数目。在定义子网掩码前，必须弄清楚本来使用的子网数和主机数目。</p><p>定义子网掩码的步骤为：</p><ul><li>1、确定哪些组地址归我们使用。比如我们申请到的网络号为 “210.73.a.b”，该网络地址为c类IP地址，网络标识为“210.73.a”，主机标识为“b”</li><li>2、根据我们所需的子网数以及将来可能扩充到的子网数，用宿主机的一些位来定义子网掩码。比如我们需要12个子网，将来可能需要16 个。用第四个字节的前四位确定子网掩码。前四位都置为“1”，即第四个字节为“11110000”，这个数我们暂且称作新的二进制子网掩码</li><li>3、把对应初始网络的各个位都置为“1”，即前三个字节都置为“1”，则子网掩码的间断二进制形式为：“11111111.11111111.11111111.11110000”</li><li>4、把这个数转化为间断十进制形式为：“255.255.255.240”</li></ul><h2 id="_3-地址判断" tabindex="-1">3 地址判断 <a class="header-anchor" href="#_3-地址判断" aria-label="Permalink to &quot;3 地址判断&quot;">​</a></h2><p>子网掩码是用来判断任意两台计算机的IP地址是否属于同一子网络的根据</p><p>最为简单的理解就是两台计算机各自的IP地址与子网掩码进行AND运算后，如果得出的结果是相同的，则说明这两台计算机是处于同一个子 网络上的，可以进行直接的通讯</p>',13)])])}const u=e(i,[["render",o]]);export{h as __pageData,u as default};
